import os
import re

# Find all markdown files and check their depth
files_by_depth = {}

for root, dirs, files in os.walk('.'):
    for file in files:
        if file.endswith('.md'):
            path = os.path.join(root, file)
            # Count slashes to get depth
            depth = path.count('/')
            if depth not in files_by_depth:
                files_by_depth[depth] = []
            files_by_depth[depth].append(path)

print("Files by depth:")
for depth in sorted(files_by_depth.keys()):
    print(f"\nDepth {depth} ({depth - 1} parent dirs needed):")
    # Only show target directories
    for f in files_by_depth[depth]:
        if any(x in f for x in ['Areas', '02-PROJECTS', '01-DAILY', '_ops', '03-NOTES', '04-RESOURCES', '07-AI']):
            print(f"  {f}")

